function dashboardHeroPool(){
const pool=[];
const seen=new Set();
for(const item of[...(state.tmdbTrending?.tv||[]),...(state.tmdbTrending?.movie||[])]){
if(!item||!item.id)continue;
const key=`${item.media_type || (item.title ? "movie" : "tv")}-${item.id}`;
if(seen.has(key))continue;
seen.add(key);
pool.push(item);
}
return pool;
}
